                ((float4*)(r + 640))[q] = r5;
            }
        }

        /// <summary>Column program: 8 instructions, 6 registers.</summary>
        private static void Column(float* r, SplinePoint* points, int lanes, uint seed){
            int quads = (lanes + 3) >> 2;
            float4* sv = stackalloc float4[4];
            for (int q = 0; q < quads; q++){
                float4 r0 = ((float4*)r)[q];
                float4 r2 = ((float4*)(r + 256))[q];
                float4 r3, r4, r5;
                {
                    float4 nx = r0, nz = r2;
                    float4 n = float4.zero;
                    n = n + SimplexLanes.Noise2(nx * math.asfloat(0x3B23D70Au), nz * math.asfloat(0x3B23D70Au), seed, 0x113869D9u) * math.asfloat(0x3F2AAAABu);
                    n = n + SimplexLanes.Noise2(nx * math.asfloat(0x3BA3D70Au), nz * math.asfloat(0x3BA3D70Au), seed, 0xF231A3CCu) * math.asfloat(0x3EAAAAABu);
                    r3 = n;
                }
                r4 = r3 * math.asfloat(0x42F00000u);
                {
                    float4 nx = r0 + r4, nz = r2;
                    float4 n = float4.zero;
                    n = n + SimplexLanes.Noise2(nx * math.asfloat(0x3A91A2B4u), nz * math.asfloat(0x3A91A2B4u), seed, 0x8682AA69u) * math.asfloat(0x3F088889u);
                    n = n + SimplexLanes.Noise2(nx * math.asfloat(0x3B11A2B4u), nz * math.asfloat(0x3B11A2B4u), seed, 0x61F55131u) * math.asfloat(0x3E888889u);
                    n = n + SimplexLanes.Noise2(nx * math.asfloat(0x3B91A2B4u), nz * math.asfloat(0x3B91A2B4u), seed, 0xE426AC8Fu) * math.asfloat(0x3E088889u);
                    n = n + SimplexLanes.Noise2(nx * math.asfloat(0x3C11A2B4u), nz * math.asfloat(0x3C11A2B4u), seed, 0x88A9A209u) * math.asfloat(0x3D888889u);
                    r3 = n;
                }
                {
                    float4 nx = r0, nz = r2;
                    float4 n = float4.zero;
                    n = n + SimplexLanes.Noise2(nx * math.asfloat(0x3B03126Fu), nz * math.asfloat(0x3B03126Fu), seed, 0xFD39B6E5u) * math.asfloat(0x3F124925u);
                    n = n + SimplexLanes.Noise2(nx * math.asfloat(0x3B83126Fu), nz * math.asfloat(0x3B83126Fu), seed, 0x6D667EC2u) * math.asfloat(0x3E924925u);
                    n = n + SimplexLanes.Noise2(nx * math.asfloat(0x3C03126Fu), nz * math.asfloat(0x3C03126Fu), seed, 0xFC797B41u) * math.asfloat(0x3E124925u);
                    r4 = n;
                }
                sv[0] = math.asfloat(0x3F19999Au);
                sv[1] = math.asfloat(0x3E800000u);
                sv[2] = math.asfloat(0x3D4CCCCDu);
                r5 = GraphKernels.Spline(r4, points + 10, sv, 3, 0);
                sv[0] = math.asfloat(0xBF19999Au);
                sv[1] = math.asfloat(0xBDCCCCCDu);
                sv[2] = r5;
                sv[3] = math.asfloat(0x3F666666u);
                r4 = GraphKernels.Spline(r3, points + 13, sv, 4, 0);
                r3 = r4 * math.asfloat(0x42C00000u);
                r4 = r3 + math.asfloat(0x42800000u);
                ((float4*)(r + 512))[q] = r4;
            }
        }
    }
}
